import java.util.Scanner;

public class Main {
    public static double myAbs(double val) {
        return val < 0 ? -val : val;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        int res_x = 0;
        int res_y = 0;
        double min_diff = 1e100;

        for (int i = 1; i <= n; i++) {
            int x = i;
            int y_upper = (int)((double)a / b * i);
            int y_lower = y_upper + 1;

            double diff_upper = myAbs((double)a / b - (double)y_upper / x);
            double diff_lower = myAbs((double)a / b - (double)y_lower / x);

            if (min_diff > diff_upper) {
                min_diff = diff_upper;
                res_x = y_upper;
                res_y = x;
            }
            if (min_diff > diff_lower) {
                min_diff = diff_lower;
                res_x = y_lower;
                res_y = x;
            }
        }
        System.out.println(res_x + "/" + res_y);
        sc.close();
    }
}
